#!/usr/bin/env bash
# Generate and install platform-specific typelibs (GLibWin32-2.0, GioWin32-2.0)
# that glib 2.88.0's girepository auto-loads at runtime.
#
# Without these typelibs, every PyGObject application emits:
#   GLib-GIRepository-CRITICAL **: Unable to load platform-specific GIO
#   introspection data: Typelib file for namespace 'GLibWin32' not found
#
# The vcpkg glib port builds with -Dintrospection=disabled, so these are
# never generated by glib itself.  We compile hand-written GIR files with
# g-ir-compiler (already installed by the gobject-introspection port).
#
# We also post-process the existing GLib-2.0.gir to remove g_win32_*
# symbols that the gobject-introspection port included by scanning
# gwin32.h.  Without this, PyGObject 3.56.3 emits "Name conflict for
# platform-specific symbol" warnings (pygobject bug #760).
#
# Usage: ./generate-platform-typelibs.sh <vcpkg_installed_triplet_dir>
# Example: ./generate-platform-typelibs.sh vcpkg_installed/x86-windows
set -euo pipefail

dir="${1:?usage: $0 <triplet_dir>}"
script_dir="$(cd "$(dirname "$0")" && pwd)"

gir_dir="$dir/share/gir-1.0"
typelib_dir="$dir/lib/girepository-1.0"
gi_tools_dir="$dir/tools/gobject-introspection"
g_ir_compiler="$gi_tools_dir/g-ir-compiler.exe"

if [ ! -f "$g_ir_compiler" ]; then
    echo "ERROR: g-ir-compiler not found at $g_ir_compiler" >&2
    exit 1
fi

if [ ! -d "$gir_dir" ]; then
    echo "ERROR: GIR directory not found: $gir_dir" >&2
    exit 1
fi

if [ ! -d "$typelib_dir" ]; then
    echo "ERROR: typelib directory not found: $typelib_dir" >&2
    exit 1
fi

echo "=== Generating platform-specific typelibs ==="

# 1. Post-process GLib-2.0.gir to remove win32 symbols
#    (prevents PyGObject name-conflict warnings)
python3 "$script_dir/gir/filter_glib_gir.py" \
    "$gir_dir/GLib-2.0.gir" "$gir_dir/GLib-2.0.gir.filtered"

mv "$gir_dir/GLib-2.0.gir.filtered" "$gir_dir/GLib-2.0.gir"

# Recompile GLib-2.0.typelib from the filtered GIR
"$g_ir_compiler" \
    --includedir="$gir_dir" \
    --output="$typelib_dir/GLib-2.0.typelib" \
    "$gir_dir/GLib-2.0.gir"
echo "OK: Recompiled GLib-2.0.typelib (win32 symbols removed)"

# 2. Compile and install GLibWin32-2.0.typelib
"$g_ir_compiler" \
    --includedir="$gir_dir" \
    --output="$typelib_dir/GLibWin32-2.0.typelib" \
    "$script_dir/gir/GLibWin32-2.0.gir"
cp "$script_dir/gir/GLibWin32-2.0.gir" "$gir_dir/"
echo "OK: Installed GLibWin32-2.0.typelib + GLibWin32-2.0.gir"

# 3. Compile and install GioWin32-2.0.typelib
"$g_ir_compiler" \
    --includedir="$gir_dir" \
    --output="$typelib_dir/GioWin32-2.0.typelib" \
    "$script_dir/gir/GioWin32-2.0.gir"
cp "$script_dir/gir/GioWin32-2.0.gir" "$gir_dir/"
echo "OK: Installed GioWin32-2.0.typelib + GioWin32-2.0.gir"

echo "=== Platform-specific typelibs generated successfully ==="
